# Audit script: scripts/react18_audit.js
// Usage: node scripts/react18_audit.js --root . --out react18-audit.json
// Requires: npm install --save-dev @babel/parser @babel/traverse glob minimist

const fs = require('fs');
const path = require('path');
const glob = require('glob');
const parser = require('@babel/parser');
const traverse = require('@babel/traverse').default;
const argv = require('minimist')(process.argv.slice(2));

const ROOT = path.resolve(argv.root || '.');
const OUT = argv.out || 'react18-audit.json';

const exts = ['js','jsx','ts','tsx'];
const patterns = exts.map(e => `${ROOT}/**/*.${e}`);
const ignore = ['**/node_modules/**','**/dist/**','**/build/**'];

function collectFiles() {
  const files = new Set();
  patterns.forEach(pat => {
    glob.sync(pat, {ignore}).forEach(f => files.add(f));
  });
  return Array.from(files).sort();
}

function parseFile(src, file) {
  try {
    return parser.parse(src, {
      sourceType: 'unambiguous',
      plugins: [
        'jsx',
        'classProperties',
        'optionalChaining',
        'nullishCoalescingOperator',
        'objectRestSpread',
        'decorators-legacy',
        'dynamicImport',
        'typescript'
      ]
    });
  } catch (err) {
    return null;
  }
}

function analyzeAst(ast, src) {
  const result = {
    classComponents: [],
    usesReactDOMRender: false,
    usesReactDOMCreateRoot: false,
    usesFindDOMNode: false,
    imports: [],
    usesThisRefs: false,
    usesStringRefs: false,
    usesCallbackRefs: false,
    usesLegacyContextAPI: false,
    testsUsingEnzymeOrTestRenderer: false,
    hasJSX: false
  };

  traverse(ast, {
    ImportDeclaration(path) {
      const src = path.node.source && path.node.source.value;
      if (src) result.imports.push(src);
      if (src === 'react-dom') {
        // check specifiers for render/createRoot use (we will still detect by member expressions)
      }
      if (src && (src.includes('enzyme') || src === 'react-test-renderer')) {
        result.testsUsingEnzymeOrTestRenderer = true;
      }
    },

    JSXElement(path) {
      result.hasJSX = true;
      const opening = path.node.openingElement;
      if (opening && opening.attributes) {
        opening.attributes.forEach(attr => {
          if (!attr) return;
          if (attr.type === 'JSXAttribute' && attr.name && attr.name.name === 'ref') {
            if (!attr.value) return; // e.g. ref={someIdentifier}
            if (attr.value.type === 'StringLiteral') {
              result.usesStringRefs = true;
            } else if (attr.value.type === 'JSXExpressionContainer') {
              const expr = attr.value.expression;
              if (expr && (expr.type === 'ArrowFunctionExpression' || expr.type === 'FunctionExpression')) {
                result.usesCallbackRefs = true;
              }
              if (expr && expr.type === 'Identifier') {
                // could be createRef or callback variable - leave as generic ref usage
              }
            }
          }
        });
      }
    },

    CallExpression(path) {
      const callee = path.node.callee;
      // findDOMNode(...)
      if (callee.type === 'Identifier' && callee.name === 'findDOMNode') result.usesFindDOMNode = true;
      // ReactDOM.render / ReactDOM.createRoot
      if (callee.type === 'MemberExpression' && callee.object && callee.property) {
        const obj = callee.object;
        const prop = callee.property;
        const objName = obj.type === 'Identifier' ? obj.name : (obj.type === 'MemberExpression' && obj.object && obj.object.name ? obj.object.name : null);
        const propName = prop.type === 'Identifier' ? prop.name : null;
        if (objName === 'ReactDOM' && propName === 'render') result.usesReactDOMRender = true;
        if (objName === 'ReactDOM' && propName === 'createRoot') result.usesReactDOMCreateRoot = true;
      }
      // this.setState(...)
      if (callee.type === 'MemberExpression' && callee.object.type === 'ThisExpression' && callee.property.name === 'setState') {
        // we'll attribute this to nearest enclosing class when traversing classes
      }
    }
  });

  // For class-specific details we do another traversal to capture methods and usages per class
  traverse(ast, {
    ClassDeclaration(path) {
      const node = path.node;
      const superClass = node.superClass;
      let isReactComponent = false;
      let superName = null;
      if (superClass) {
        if (superClass.type === 'MemberExpression') {
          // e.g. React.Component
          const obj = superClass.object && superClass.object.name;
          const prop = superClass.property && superClass.property.name;
          if (obj === 'React' && (prop === 'Component' || prop === 'PureComponent')) {
            isReactComponent = true; superName = `${obj}.${prop}`;
          }
        } else if (superClass.type === 'Identifier') {
          const name = superClass.name;
          if (name === 'Component' || name === 'PureComponent') { isReactComponent = true; superName = name; }
        }
      }
      if (!isReactComponent) return;

      const className = node.id ? node.id.name : '(Anonymous)';
      const methods = [];
      const methodNames = new Set();
      const usages = {
        usesSetState: false,
        usesRefs: false,
        usesStringRefs: false,
        usesCallbackRefs: false,
        usesLegacyContextAPI: false,
        deprecatedLifecycles: [],
        unsafeLifecycles: [],
        usesGetDerivedStateFromProps: false,
        usesFindDOMNode: false
      };

      node.body.body.forEach(el => {
        if (el.type === 'ClassMethod' || el.type === 'ClassProperty') {
          const name = el.key && el.key.name ? el.key.name : (el.key && el.key.value ? el.key.value : '<computed>');
          methodNames.add(name);
          methods.push(name);
          // legacy context static members
          if (name === 'contextTypes' || name === 'childContextTypes' || name === 'getChildContext') {
            usages.usesLegacyContextAPI = true;
          }
          // detect getDerivedStateFromProps
          if (name === 'getDerivedStateFromProps') usages.usesGetDerivedStateFromProps = true;
          // deprecated lifecycles
          if (['componentWillMount','componentWillReceiveProps','componentWillUpdate'].includes(name)) {
            usages.deprecatedLifecycles.push(name);
            usages.unsafeLifecycles = usages.unsafeLifecycles.concat(name);
          }
          if ((name && name.startsWith('UNSAFE_')) ) {
            usages.unsafeLifecycles.push(name);
          }
        }
      });

      // Traverse class body to find this.setState, this.refs, findDOMNode, string refs, callback refs
      path.traverse({
        CallExpression(inner) {
          const callee = inner.node.callee;
          if (callee.type === 'MemberExpression' && callee.object.type === 'ThisExpression' && callee.property.name === 'setState') {
            usages.usesSetState = true;
          }
          if (callee.type === 'Identifier' && callee.name === 'findDOMNode') {
            usages.usesFindDOMNode = true;
          }
        },
        MemberExpression(inner) {
          const me = inner.node;
          if (me.object && me.object.type === 'ThisExpression' && me.property && me.property.name === 'refs') {
            usages.usesRefs = true; usages.usesThisRefs = true;
          }
        },
        JSXAttribute(inner) {
          const attr = inner.node;
          if (attr.name && attr.name.name === 'ref') {
            if (!attr.value) return;
            if (attr.value.type === 'StringLiteral') usages.usesStringRefs = true;
            if (attr.value.type === 'JSXExpressionContainer') {
              const expr = attr.value.expression;
              if (expr && (expr.type === 'ArrowFunctionExpression' || expr.type === 'FunctionExpression')) usages.usesCallbackRefs = true;
            }
            usages.usesRefs = usages.usesRefs || usages.usesStringRefs || usages.usesCallbackRefs;
          }
        }
      });

      result.classComponents.push({
        name: className,
        superClass: superName,
        fileMethods: methods,
        methodCount: methods.length,
        usages
      });

    },

    // also handle ClassExpression assigned to variables: const X = class extends React.Component {}
    VariableDeclarator(path) {
      const init = path.node.init;
      if (!init) return;
      if (init.type === 'ClassExpression') {
        const superClass = init.superClass;
        let isReactComponent = false;
        let superName = null;
        if (superClass) {
          if (superClass.type === 'MemberExpression') {
            const obj = superClass.object && superClass.object.name;
            const prop = superClass.property && superClass.property.name;
            if (obj === 'React' && (prop === 'Component' || prop === 'PureComponent')) {
              isReactComponent = true; superName = `${obj}.${prop}`;
            }
          } else if (superClass.type === 'Identifier') {
            const name = superClass.name;
            if (name === 'Component' || name === 'PureComponent') { isReactComponent = true; superName = name; }
          }
        }
        if (!isReactComponent) return;
        const className = path.node.id && path.node.id.name ? path.node.id.name : '(Anonymous)';
        const methods = [];
        init.body.body.forEach(el => {
          const name = el.key && el.key.name ? el.key.name : '<computed>';
          methods.push(name);
        });
        result.classComponents.push({ name: className, superClass: superName, fileMethods: methods, methodCount: methods.length, usages: {} });
      }
    }
  });

  // Secondary pass to detect any top-level findDOMNode or JSX string refs
  traverse(ast, {
    CallExpression(path) {
      const callee = path.node.callee;
      if (callee.type === 'Identifier' && callee.name === 'findDOMNode') result.usesFindDOMNode = true;
      if (callee.type === 'MemberExpression' && callee.object && callee.object.name === 'ReactDOM') {
        const prop = callee.property && callee.property.name;
        if (prop === 'render') result.usesReactDOMRender = true;
        if (prop === 'createRoot') result.usesReactDOMCreateRoot = true;
      }
    },
    JSXAttribute(path) {
      const attr = path.node;
      if (attr.name && attr.name.name === 'ref') {
        if (!attr.value) return;
        if (attr.value.type === 'StringLiteral') result.usesStringRefs = true;
        if (attr.value.type === 'JSXExpressionContainer') {
          const expr = attr.value.expression;
          if (expr && (expr.type === 'ArrowFunctionExpression' || expr.type === 'FunctionExpression')) result.usesCallbackRefs = true;
        }
        result.usesRefs = result.usesRefs || result.usesStringRefs || result.usesCallbackRefs;
      }
    }
  });

  return result;
}

function fileSummary(file, data) {
  const hasClass = data.classComponents && data.classComponents.length > 0;
  return {
    file: path.relative(ROOT, file),
    hasClass,
    classCount: data.classComponents.length,
    usesReactDOMRender: data.usesReactDOMRender,
    usesReactDOMCreateRoot: data.usesReactDOMCreateRoot,
    usesFindDOMNode: data.usesFindDOMNode,
    usesThisRefs: data.usesThisRefs || data.usesRefs,
    usesStringRefs: data.usesStringRefs,
    usesCallbackRefs: data.usesCallbackRefs,
    usesLegacyContextAPI: data.usesLegacyContextAPI,
    testsUsingEnzymeOrTestRenderer: data.testsUsingEnzymeOrTestRenderer,
    imports: data.imports
  };
}

function run() {
  const files = collectFiles();
  const out = { files: [], summary: { totalFiles: files.length, totalClassComponents: 0, filesWithRender: 0, filesWithCreateRoot: 0, filesUsingFindDOMNode: 0, filesUsingStringRefs: 0, filesUsingThisRefs: 0, filesUsingEnzymeOrTestRenderer: 0 } };

  files.forEach(file => {
    const src = fs.readFileSync(file, 'utf8');
    const ast = parseFile(src, file);
    if (!ast) {
      // unable to parse; include as skipped
      out.files.push({ file: path.relative(ROOT,file), parseError: true });
      return;
    }
    const analysis = analyzeAst(ast, src);
    const summary = fileSummary(file, analysis);
    out.files.push({ file: summary.file, parseError: false, details: analysis });

    out.summary.totalClassComponents += analysis.classComponents.length;
    if (summary.usesReactDOMRender) out.summary.filesWithRender++;
    if (summary.usesReactDOMCreateRoot) out.summary.filesWithCreateRoot++;
    if (summary.usesFindDOMNode) out.summary.filesUsingFindDOMNode++;
    if (summary.usesStringRefs) out.summary.filesUsingStringRefs++;
    if (summary.usesThisRefs) out.summary.filesUsingThisRefs++;
    if (summary.testsUsingEnzymeOrTestRenderer) out.summary.filesUsingEnzymeOrTestRenderer++;
  });

  fs.writeFileSync(OUT, JSON.stringify(out, null, 2), 'utf8');
  console.log(`Audit written to ${OUT} — files scanned: ${out.summary.totalFiles}, class components: ${out.summary.totalClassComponents}`);
}

run();

